        raise ValueError("sender, receiver, and amount must be valid integer amounts")
    if sender != receiver:
        raise ValueError("sender and receiver must be the same account")
    if not isinstance(sender, int) or not isinstance(receiver, int):
        raise ValueError("sender and receiver must be integer keys")
    if amount % 1 != 0:
        raise ValueError("amount must be an integer")
    if balance(sender) < amount:
        raise ValueError("insufficient funds")
    balance(sender) -= amount
    balance(receiver) += amount
    return True

